const {chromium,firefox}=require('/work/node_modules/playwright');
const {expect}=require('/work/node_modules/@playwright/test');
const fs=require('node:fs');
const crypto=require('node:crypto');
(async()=>{
 const results=[];
 for(const [name,type] of Object.entries({chromium,firefox})){
  const browser=await type.launch({headless:true});
  try{
   const page=await browser.newPage({viewport:{width:390,height:844}});
   await page.goto('http://127.0.0.1:12805/admin/login');
   await page.locator('[data-slot=login-username]').fill('admin@example.com');
   await page.locator('[data-slot=login-password]').fill(process.env.PINVI_COMMON_LIVE_PASSWORD);
   await page.locator('[data-slot=login-submit]').click();
   await expect(page).toHaveURL(/\/admin$/);
   await page.goto('http://127.0.0.1:12805/admin/etl');
   const panel=page.getByTestId('admin-common-dagster');
   await expect(panel).toContainText('pinvi_email_outbox_job');
   const region=panel.getByRole('region',{name:'최근 Dagster 실행 표'});
   await region.scrollIntoViewIfNeeded();
   const sizes=await region.evaluate(e=>({viewport:e.clientWidth,content:e.scrollWidth,root:document.documentElement.scrollWidth}));
   expect(sizes.root).toBeLessThanOrEqual(391);expect(sizes.content).toBeGreaterThan(sizes.viewport);
   await region.focus();await expect(region).toBeFocused();
   await page.keyboard.press('ArrowRight');
   await expect.poll(()=>region.evaluate(e=>e.scrollLeft),{timeout:3000}).toBeGreaterThan(0);
   const offset=await region.evaluate(e=>e.scrollLeft);
   await region.evaluate(e=>{e.scrollLeft=0});
   const box=await region.locator('button.dagster-run-select').first().boundingBox();
   expect(box.width).toBeGreaterThan(100);expect(box.height).toBeLessThan(100);
   await page.screenshot({path:'/evidence/'+name+'-mobile-readable.png',fullPage:false});
   results.push({browser:name,width:390,...sizes,keyboardScrollLeft:offset,jobButton:{width:box.width,height:box.height}});
  }finally{await browser.close();}
 }
